import pty, os, subprocess, struct, fcntl, termios, time, os as _os, re
def run(rows):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", rows, 80, 0, 0))
    env={**_os.environ, 'DSTASK_GIT_REPO':'/tmp/many/repo'}
    env.pop('DSTASK_FAKE_PTY', None)
    p = subprocess.Popen(['./executable','next'], stdin=slave, stdout=slave, stderr=slave, env=env)
    time.sleep(0.5)
    _flags = fcntl.fcntl(master, fcntl.F_GETFL)
    fcntl.fcntl(master, fcntl.F_SETFL, _flags | _os.O_NONBLOCK)
    try: data=_os.read(master, 20000)
    except: data=b''
    p.wait(timeout=2)
    _os.close(master); _os.close(slave)
    ansi=re.compile(br'\x1b\[[0-9;]*m')
    lines=[ansi.sub(b'', l) for l in data.split(b'\r\n')]
    for l in lines:
        if b'tasks' in l: return l.decode()
for r in [5,6,7,8,9,10,11,12,15,20,24,30,50]:
    print(r, run(r))
PY"}

