		// trim spaces
		start := 0
		end := len(trimmed)
		for start < end && (trimmed[start] == ' ' || trimmed[start] == '\t') {
			start++
		}
		for end > start && (trimmed[end-1] == ' ' || trimmed[end-1] == '\t' || trimmed[end-1] == '\n' || trimmed[end-1] == '\r') {
			end--
		}
		t = trimmed[start:end]
		// lowercase
		lower := ""
		for _, c := range t {
			if c >= 'A' && c <= 'Z' {
				lower += string(c + 32)
			} else {
