// YAML escaping for simple strings
func yamlEscape(s string) string {
	if s == "" {
		return "\"\""
	}
	// check if needs quoting
	// original uses yaml.v2 rules: plain allowed unless contains special chars
	// For simplicity, replicate observed:
	// - empty -> ""
	// - contains ": " or ":" at end? -> single quotes? Actually 'test: colon' was single-quoted
	// - contains newline -> literal block
	// We'll implement logic to match yaml.v2 for our cases
	if strings.Contains(s, "\n") {
		// use literal block
		// check if needs |2- vs |-
		// if starts with \n or has leading spaces? use |2-
		// For now, determine: if strings.HasPrefix(s, "\n") then |2-
		// else |-
		if strings.HasPrefix(s, "\n") || strings.HasPrefix(s, " ") {
			// use |2-
			lines := strings.Split(s, "\n")
			var b strings.Builder
			b.WriteString("|2-\n")
			for i, line := range lines {
				if i == 0 && line == "" {
					b.WriteString("\n")
				} else {
					if line == "" {
						b.WriteString("\n")
					} else {
						b.WriteString("  " + line + "\n")
					}
				}
			}
			// yaml.v2 output for "\nfinished!" is:
			// notes: |2-
			//
			//   finished!
			// Our builder gives "|2-\n\n  finished!\n" which matches? Need to check trailing newline handling
			// The file ends with next key, so last line has \n, that's fine
			// Remove last \n? No, keep as is, caller will add next line
			s2 := b.String()
			// remove trailing \n? Actually yaml block ends with \n, then next key on next line
			// Our b ends with \n, good
			// But need to handle: for s="\nfinished!", lines=["","finished!"], we produce "|2-\n\n  finished!\n" correct
			// For s="hello\nsecond", lines=["hello","second"], produce "|-\n  hello\n  second\n" (but we use |2- here, wrong)
			// So only use |2- when prefix \n or space, else |-
			return strings.TrimSuffix(s2, "\n")
		}
		lines := strings.Split(s, "\n")
		var b strings.Builder
		b.WriteString("|-\n")
		for _, line := range lines {
			if line == "" {
				b.WriteString("\n")
			} else {
				b.WriteString("  " + line + "\n")
			}
		}
		return strings.TrimSuffix(b.String(), "\n")
	}
	// check plain allowed: yaml plain cannot contain: :#{}[],&*!|>'"%@` etc at start, or ": " inside, or leading/trailing spaces, or quotes?
	// Simplify: if s contains ": " or ends with ":" then quote with single quotes
	// Also if contains " #"? Let's just handle colon case and empty
	needsQuote := false
	if strings.Contains(s, ": ") || strings.HasSuffix(s, ":") {
		needsQuote = true
	}
	// also if starts with special chars: - ? : , [ ] { } # & * ! | > ' " % @ ` ?
	if len(s) > 0 {
		c := s[0]
		if strings.ContainsRune("-?:,[]{}#&*!|>'\"%@`", rune(c)) {
			// check: "quote \"test\"" starts with q, so plain, even though contains "
			// "single 'quote' test" starts with s, plain
			// So leading " or ' would need quotes, but our cases don't have that
			needsQuote = true
		}
	}
	// also if contains " #" or trailing space?
	if strings.HasPrefix(s, " ") || strings.HasSuffix(s, " ") {
		needsQuote = true
	}
	if needsQuote {
		// use single quotes, escape single by doubling?
		escaped := strings.ReplaceAll(s, "'", "''")
		return "'" + escaped + "'"
	}
	return s
}

func yamlQuoteEmpty(s string) string {
	if s == "" {
		return "\"\""
	}
	return yamlEscape(s)
}

func (t *Task) ToYAML() string {
	var b strings.Builder
	// summary
	b.WriteString("summary: " + yamlEscape(t.Summary) + "\n")
	// notes
	b.WriteString("notes: " + yamlQuoteEmpty(t.Notes) + "\n")
	// tags
	if len(t.Tags) == 0 {
		b.WriteString("tags: []\n")
	} else {
		b.WriteString("tags:\n")
		for _, tag := range t.Tags {
			// tags are simple, no quoting needed? If tag contains special? Tags are alphanumeric? Just plain
			b.WriteString("- " + tag + "\n")
		}
	}
	// project
	if t.Project == "" {
		b.WriteString("project: \"\"\n")
	} else {
		b.WriteString("project: " + yamlEscape(t.Project) + "\n")
	}
	b.WriteString("priority: " + t.Priority + "\n")
	if t.DelegatedTo == "" {
		b.WriteString("delegatedto: \"\"\n")
	} else {
		b.WriteString("delegatedto: " + yamlEscape(t.DelegatedTo) + "\n")
	}
	if len(t.Subtasks) == 0 {
		b.WriteString("subtasks: []\n")
	} else {
		b.WriteString("subtasks:\n")
		for _, s := range t.Subtasks {
			b.WriteString("- " + yamlEscape(s) + "\n")
		}
	}
	if len(t.Dependencies) == 0 {
		b.WriteString("dependencies: []\n")
	} else {
		b.WriteString("dependencies:\n")
		for _, s := range t.Dependencies {
			b.WriteString("- " + yamlEscape(s) + "\n")
		}
	}
	b.WriteString("created: " + formatTime(t.Created) + "\n")
	b.WriteString("resolved: " + formatTime(t.Resolved) + "\n")
	b.WriteString("due: " + formatTime(t.Due) + "\n")
	return b.String()
}

func formatTime(t time.Time) string {
	if t.IsZero() {
		return "0001-01-01T00:00:00Z"
	}
	// use RFC3339Nano in UTC?
	u := t.UTC()
	// Go's time.RFC3339Nano removes trailing zeros? Use Format with RFC3339Nano
	return u.Format(time.RFC3339Nano)
}

func parseTime(s string) time.Time {
	s = strings.TrimSpace(s)
	// remove quotes?
	if len(s) >= 2 && ((s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'')) {
		s = s[1 : len(s)-1]
	}
	// try RFC3339Nano, RFC3339, etc
	formats := []string{time.RFC3339Nano, time.RFC3339, "2006-01-02T15:04:05Z", "2006-01-02"}
	for _, f := range formats {
		if t, err := time.Parse(f, s); err == nil {
			return t
		}
	}
	return time.Time{}
}

// Parse YAML file content into Task (status and uuid set separately)
func parseYAML(content string, uuid, status string) (*Task, error) {
	t := &Task{UUID: uuid, Status: status, Priority: "P2"}
	lines := strings.Split(content, "\n")
	i := 0
	for i < len(lines) {
		line := lines[i]
		if strings.TrimSpace(line) == "" {
			i++
			continue
		}
		// find key: value
		// keys are: summary, notes, tags, project, priority, delegatedto, subtasks, dependencies, created, resolved, due
		if strings.HasPrefix(line, "summary:") {
			val := strings.TrimSpace(line[len("summary:"):])
			if val == "|-" || val == "|2-" || strings.HasPrefix(val, "|") {
				// literal block: following indented lines
				var blockLines []string
				i++
				// determine indent? For |- it's 2 spaces? For |2- it's 2 spaces as well?
				for i < len(lines) {
					l := lines[i]
					if l == "" {
						blockLines = append(blockLines, "")
						i++
						continue
					}
					if strings.HasPrefix(l, "  ") {
						blockLines = append(blockLines, l[2:])
						i++
					} else if strings.TrimSpace(l) == "" {
						blockLines = append(blockLines, "")
						i++
					} else {
						break
					}
				}
				// yaml literal: join with \n, chomping? |- strips final newline, |2- also strips?
				// For our cases, block content is as stored (without trailing \n)
				// But need to handle leading blank line for |2- with \n prefix?
				// For notes "\nfinished!": block is ["", "finished!"]? Actually file shows:
				// notes: |2-
				//
				//   finished!
				// That's lines: "notes: |2-", "", "  finished!"
				// Our blockLines would be ["", "finished!"] -> join => "\nfinished!" correct
				// For summary "multi\nline": "summary: |-", "  multi", "  line" => ["multi","line"] => "multi\nline" correct
				t.Summary = strings.Join(blockLines, "\n")
				continue
			} else {
				// single line, handle quotes
				t.Summary = yamlUnescape(val)
				i++
			}
		} else if strings.HasPrefix(line, "notes:") {
			val := strings.TrimSpace(line[len("notes:"):])
			if val == "|-" || val == "|2-" || strings.HasPrefix(val, "|") {
				var blockLines []string
				i++
				for i < len(lines) {
