			}
		} else if strings.HasPrefix(line, "tags:") {
			val := strings.TrimSpace(line[len("tags:"):])
			if val == "[]" {
				t.Tags = []string{}
				i++
			} else if val == "" {
				// list following
				var tags []string
				i++
				for i < len(lines) {
					l := strings.TrimSpace(lines[i])
					if strings.HasPrefix(l, "- ") {
						tag := strings.TrimSpace(l[2:])
						tag = yamlUnescape(tag)
						tags = append(tags, tag)
