					} else if l == "" {
						i++
					} else {
						break
					}
				}
				t.Tags = tags
				if t.Tags == nil {
					t.Tags = []string{}
				}
				continue
			} else {
				i++
			}
		} else if strings.HasPrefix(line, "project:") {
			val := strings.TrimSpace(line[len("project:"):])
			t.Project = yamlUnescape(val)
			// empty "" => ""? yamlUnescape("\"\"") => "" correct
			i++
		} else if strings.HasPrefix(line, "priority:") {
			val := strings.TrimSpace(line[len("priority:"):])
			t.Priority = yamlUnescape(val)
			if t.Priority == "" {
				t.Priority = "P2"
			}
			i++
		} else if strings.HasPrefix(line, "delegatedto:") {
			val := strings.TrimSpace(line[len("delegatedto:"):])
			t.DelegatedTo = yamlUnescape(val)
			i++
		} else if strings.HasPrefix(line, "subtasks:") {
			val := strings.TrimSpace(line[len("subtasks:"):])
			if val == "[]" {
				t.Subtasks = []string{}
				i++
			} else if val == "" {
				var arr []string
				i++
				for i < len(lines) {
					l := strings.TrimSpace(lines[i])
					if strings.HasPrefix(l, "- ") {
