				if t.Subtasks == nil {
					t.Subtasks = []string{}
				}
				continue
			} else {
				i++
			}
		} else if strings.HasPrefix(line, "dependencies:") {
			val := strings.TrimSpace(line[len("dependencies:"):])
			if val == "[]" {
				t.Dependencies = []string{}
				i++
			} else if val == "" {
				var arr []string
				i++
				for i < len(lines) {
