				continue
			} else {
				i++
			}
		} else if strings.HasPrefix(line, "created:") {
			val := strings.TrimSpace(line[len("created:"):])
			t.Created = parseTime(val)
			i++
		} else if strings.HasPrefix(line, "resolved:") {
			val := strings.TrimSpace(line[len("resolved:"):])
