		} else if strings.HasPrefix(line, "due:") {
			val := strings.TrimSpace(line[len("due:"):])
			t.Due = parseTime(val)
			i++
		} else {
			i++
		}
	}
	if t.Tags == nil {
		t.Tags = []string{}
	}
	if t.Subtasks == nil {
		t.Subtasks = []string{}
	}
	if t.Dependencies == nil {
		t.Dependencies = []string{}
	}
	return t, nil
}

func yamlUnescape(s string) string {
	s = strings.TrimSpace(s)
	if s == "" {
		return ""
	}
	if s == "\"\"" || s == "''" {
		return ""
	}
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		inner := s[1 : len(s)-1]
		inner = strings.ReplaceAll(inner, "''", "'")
		return inner
	}
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		// handle double-quoted? Use simple unescape?
		inner := s[1 : len(s)-1]
		// handle \" and \\?
		inner = strings.ReplaceAll(inner, "\\\"", "\"")
		inner = strings.ReplaceAll(inner, "\\\\", "\\")
		return inner
	}
	return s
}

