func sortTasks(tasks []*Task) {
	sort.Slice(tasks, func(i, j int) bool {
		// priority order: P0 < P1 < P2 < P3
		pi := priorityOrder(tasks[i].Priority)
		pj := priorityOrder(tasks[j].Priority)
		if pi != pj {
			return pi < pj
		}
		// then creation date? Most recent last? Help says "most recent last" for next? Actually next shows most important first? For same priority, older first? In our earlier test, task C (older) before D/E (newer) for same P2. So created ascending.
		if !tasks[i].Created.Equal(tasks[j].Created) {
			return tasks[i].Created.Before(tasks[j].Created)
		}
		return tasks[i].ID < tasks[j].ID
	})
}

func priorityOrder(p string) int {
	switch p {
	case "P0":
		return 0
	case "P1":
		return 1
	case "P2":
		return 2
	case "P3":
		return 3
	default:
		return 2
	}
}
