func getTermSize() (int, int) {
	type winsize struct {
		Row    uint16
		Col    uint16
		X      uint16
		Y      uint16
	}
	ws := &winsize{}
	_, _, _ = syscall.Syscall(syscall.SYS_IOCTL, uintptr(os.Stdout.Fd()), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
