func contextString(q Query) string {
	var parts []string
	for _, t := range q.Tags {
		parts = append(parts, "+"+t)
	}
	for _, t := range q.AntiTags {
		parts = append(parts, "-"+t)
	}
	if q.Project != "" {
		parts = append(parts, "project:"+q.Project)
	}
	for _, p := range q.AntiProjects {
		parts = append(parts, "-project:"+p)
	}
	if q.Priority != "" {
		parts = append(parts, q.Priority)
	}
	if q.DateFilter != "" {
		parts = append(parts, "due:"+q.DateFilter)
	} else if !q.Due.IsZero() {
		parts = append(parts, "due:"+q.Due.Format("2006-01-02"))
	}
	if q.Text != "" {
		parts = append(parts, q.Text)
	}
	return strings.Join(parts, " ")
}
